def http_get_json(url, timeout=20.0):
    req = urllib.request.Request(url, method="GET")
    req.add_header("Accept", "application/json")
    req.add_header("X-Agent-Protocol", "getpostingboard/1")
    with urllib.request.urlopen(req, timeout=timeout) as r:
        return json.loads(r.read().decode("utf-8"))


def http_post_form(url, fields, timeout=20.0):
    data = urllib.parse.urlencode(fields).encode("utf-8")
    req = urllib.request.Request(url, data=data, method="POST")
    req.add_header("Accept", "application/json")
    req.add_header("Content-Type", "application/x-www-form-urlencoded")
    req.add_header("X-Agent-Protocol", "getpostingboard/1")
    with urllib.request.urlopen(req, timeout=timeout) as r:
        return json.loads(r.read().decode("utf-8"))


def board_error(e):
    out = {"error": "board_error", "board_status": getattr(e, "code", None)}
    try:
        err = (json.loads(e.read().decode("utf-8")).get("error") or {})
        out["code"], out["message"] = err.get("code"), err.get("message")
    except Exception:
        pass
    try:
        if e.headers.get("Retry-After"):
            out["retry_after"] = e.headers["Retry-After"]
    except Exception:
        pass
    return out


def classify(body):
    b = (body or "").strip()
    return "agent" if b.startswith("[агент]") or b.startswith("[R ") else "human"


def normalize(items):
    out = []
    for it in items or []:
        body = (it.get("body") or "").strip()
        if body:
            out.append({"seq": int(it.get("seq", 0)), "who": classify(body),
                        "text": body, "ts": it.get("created_at", 0)})
    return out


class H(BaseHTTPRequestHandler):
    def _json(self, code, obj):
        data = json.dumps(obj, ensure_ascii=False).encode()
        self.send_response(code)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(data)))
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        self.wfile.write(data)

    def do_GET(self):
        p = urllib.parse.urlparse(self.path).path
        if p == "/":
            data = PAGE.encode()
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.send_header("Content-Length", str(len(data)))
            self.end_headers()
            self.wfile.write(data)
            return
        if p == "/api/messages":
            if DEMO:
                return self._json(200, {"messages": [
                    {"seq": 1, "who": "human", "ts": int(time.time()) - 60,
                     "text": "Это демо-режим: доска не трогается."},
                    {"seq": 2, "who": "agent", "ts": int(time.time()) - 30,
                     "text": "[агент] Демо-ответ агента."}]})
            now = time.time()
            with _lock:
                if _cache["data"] is not None and now - _cache["ts"] < CACHE_TTL:
                    return self._json(200, _cache["data"])
            try:
                d = http_get_json(f"{BASE}/b/t/{urllib.parse.quote(THREAD)}")
                payload = {"messages": normalize(d.get("items"))}
            except urllib.error.HTTPError as e:
                return self._json(502, board_error(e))
            except Exception:
                return self._json(502, {"error": "upstream_unavailable"})
            with _lock:
                _cache["ts"], _cache["data"] = time.time(), payload
            return self._json(200, payload)
        self._json(404, {"error": "not found"})

    def do_POST(self):
        p = urllib.parse.urlparse(self.path).path
        if p != "/api/send":
            return self._json(404, {"error": "not found"})
        try:
            ln = int(self.headers.get("Content-Length", 0))
        except ValueError:
            return self._json(400, {"error": "bad Content-Length"})
        if ln > POST_MAX:
            return self._json(413, {"error": "request too large"})
        try:
            payload = json.loads(self.rfile.read(ln) or b"{}")
        except Exception:
            return self._json(400, {"error": "bad json"})
        body = str(payload.get("body", "")).strip()
        if not body:
            return self._json(400, {"error": "empty body"})
        if len(body.encode()) > MSG_MAX:
            return self._json(413, {"error": "too long", "max_bytes": MSG_MAX})
        if DEMO:
            return self._json(200, {"demo": True, "seq": 0})
        rid = str(payload.get("request_id") or "")[:64] or str(uuid.uuid4())
        # шаг 1 (read-only) и шаг 2 (write) атомарны: тело между ними неизменно (N2)
        try:
            q = urllib.parse.urlencode({"reply_to": THREAD, "body": body,
                                        "request_id": rid})
            pv = http_get_json(f"{BASE}/b/preview?{q}")
            res = http_post_form(BASE + "/b/publish", {
                "ticket": pv["ticket"], "confirm": pv.get("confirm", "publish-publicly")})
        except urllib.error.HTTPError as e:
            print(f"AUDIT publish-fail rid={rid} {board_error(e)}", flush=True)
            return self._json(e.code if 400 <= e.code < 600 else 502, board_error(e))
        except Exception:
            return self._json(502, {"error": "upstream_unavailable"})
        with _lock:  # N1: своё сообщение видно сразу, без окна устаревания
            _cache["ts"] = 0.0
        seq = (res.get("post") or {}).get("seq")
        print(f"AUDIT publish ok rid={rid} seq={seq} "
              f"replayed={res.get('replayed')}", flush=True)
        return self._json(200, {"ok": True, "seq": seq,
                                "replayed": res.get("replayed", False)})

    def log_message(self, *a):
        pass


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
